import pathlib
import re
from collections import OrderedDict


class Swconfig:
    """Swconfig file handler class, with ability to modify its content."""

    FLAG_PATTERN = re.compile(r"^(?P<commented>[#\s]*)(?P<flag>\w+)\s*=\s*(?P<value>[\w-]+)(?P<comment>.*)")

    def __init__(self, file_path):
        self.swconfig_data = OrderedDict()
        self.input_file_path = file_path
        self.output_file_path = self._prepare_output_filepath()
        self._parse_swconfig()

    def modify_swconfig(self, params):
        """Append new flags to swconfig.

        :param params: List of flags and values to add to swconfig file.
        :return: path to modified swconfig file.
        """
        for line in params:
            self._parse_flag_ang_values(line)
        self._save_modified_swconfig()
        return self.output_file_path

    def _save_modified_swconfig(self):
        with open(self.output_file_path, "w") as sw_file:
            for flag, attrs in list(self.swconfig_data.items()):
                line = "".join(
                    [
                        attrs["commented"],
                        flag,
                        " = ",
                        attrs["value"],
                        attrs["comment"],
                        "\n",
                    ]
                )
                sw_file.write(line)

    def _prepare_output_filepath(self):
        path = pathlib.Path(self.input_file_path)
        new_f_name = path.stem + "_MODIFIED" + path.suffix
        return (path.parent / new_f_name).as_posix()

    def _parse_swconfig(self):
        with open(self.input_file_path) as sw_file:
            for line in sw_file:
                self._parse_flag_ang_values(line)

    def _parse_flag_ang_values(self, line):
        match = re.match(self.FLAG_PATTERN, line)
        if match:
            dict_match = match.groupdict()
            flag = self._prepare_flag(dict_match.pop("flag"))
            self.swconfig_data.update({flag: dict_match})

    @staticmethod
    def _prepare_flag(flag):
        if "x" in flag:
            leading, trailing = flag.split("x")
            flag = "x".join([leading, trailing.lstrip("0")])
        return flag


if __name__ == "__main__":
    s = Swconfig("swconfig.txt")
    s.modify_swconfig(["1234=1234", "0x0239843214  = 12343214", "0x12000b=1234 "])
